style.css:
@-moz-document domain("twitter.com"), domain("x.com") {
/* 1. Hides the 'Discover More' text content */
    /* Note: The empty container will remain visible */
    h2[role="heading"] span {
        display: none !important;
    }
    
    /* 2. Hides the 'Sourced from X' text below it */
    h2[role="heading"] + div {
        display: none !important;
    }
}
